changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.taxonomy_unassigned_chashes_384( p_collection text, p_limit int ) RETURNS TABLE(has_taxonomy boolean, chashes text[]) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_384 IS NOT NULL ) AS v ), unassigned AS ( SELECT c.chash FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND (SELECT v FROM has_tax) AND NOT EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.id = ta.topic_id WHERE ta.doc_id = c.chash AND t.collection = p_collection ) ORDER BY c.chash LIMIT p_limit ) SELECT (SELECT v FROM has_tax) AS has_taxonomy, COALESCE((SELECT array_agg(encode(u.chash, 'hex') ORDER BY u.chash) FROM unassigned u), ARRAY[]::text[]) AS chashes $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_unassigned_chashes_768( p_collection text, p_limit int ) RETURNS TABLE(has_taxonomy boolean, chashes text[]) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_768 IS NOT NULL ) AS v ), unassigned AS ( SELECT c.chash FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_768 IS NOT NULL AND (SELECT v FROM has_tax) AND NOT EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.id = ta.topic_id WHERE ta.doc_id = c.chash AND t.collection = p_collection ) ORDER BY c.chash LIMIT p_limit ) SELECT (SELECT v FROM has_tax) AS has_taxonomy, COALESCE((SELECT array_agg(encode(u.chash, 'hex') ORDER BY u.chash) FROM unassigned u), ARRAY[]::text[]) AS chashes $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_unassigned_chashes_1024( p_collection text, p_limit int ) RETURNS TABLE(has_taxonomy boolean, chashes text[]) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_1024 IS NOT NULL ) AS v ), unassigned AS ( SELECT c.chash FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_1024 IS NOT NULL AND (SELECT v FROM has_tax) AND NOT EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.id = ta.topic_id WHERE ta.doc_id = c.chash AND t.collection = p_collection ) ORDER BY c.chash LIMIT p_limit ) SELECT (SELECT v FROM has_tax) AS has_taxonomy, COALESCE((SELECT array_agg(encode(u.chash, 'hex') ORDER BY u.chash) FROM unassigned u), ARRAY[]::text[]) AS chashes $$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_384(text, int);
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_768(text, int);
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_1024(text, int);
